package com.loyalty.controller;

import com.loyalty.entity.Business;
import com.loyalty.entity.FidelityTier;
import com.loyalty.entity.User;
import com.loyalty.repository.BusinessRepository;
import com.loyalty.repository.FidelityTierRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/admin/fidelity-tiers")
public class FidelityTierController {

    private final BusinessRepository businessRepository;
    private final FidelityTierRepository fidelityTierRepository;

    public FidelityTierController(BusinessRepository businessRepository, FidelityTierRepository fidelityTierRepository) {
        this.businessRepository = businessRepository;
        this.fidelityTierRepository = fidelityTierRepository;
    }

    @GetMapping
    public ResponseEntity<?> getTiers(@AuthenticationPrincipal User owner) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            List<FidelityTier> tiers = fidelityTierRepository.findByBusinessAndIsActiveTrueOrderByCardsRequiredAsc(business);
            return ResponseEntity.ok(tiers);
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }

    @PostMapping
    public ResponseEntity<?> createTier(@AuthenticationPrincipal User owner, @RequestBody FidelityTier tier) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            if (fidelityTierRepository.findByBusinessAndCardsRequired(business, tier.getCardsRequired()).isPresent()) {
                return ResponseEntity.badRequest().body(Map.of("error", "Ya existe un nivel con " + tier.getCardsRequired() + " tarjetas"));
            }

            tier.setBusiness(business);
            tier.setId(null);
            FidelityTier saved = fidelityTierRepository.save(tier);
            return ResponseEntity.ok(saved);
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }

    @PutMapping("/{id}")
    public ResponseEntity<?> updateTier(@AuthenticationPrincipal User owner, @PathVariable Long id, @RequestBody FidelityTier tier) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            FidelityTier existing = fidelityTierRepository.findById(id)
                    .orElseThrow(() -> new RuntimeException("Tier not found"));

            if (!existing.getBusiness().getId().equals(business.getId())) {
                return ResponseEntity.status(403).body(Map.of("error", "No tienes permiso para modificar este tier"));
            }

            existing.setCardsRequired(tier.getCardsRequired());
            existing.setRewardDescription(tier.getRewardDescription());
            existing.setIsActive(tier.getIsActive());

            FidelityTier saved = fidelityTierRepository.save(existing);
            return ResponseEntity.ok(saved);
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<?> deleteTier(@AuthenticationPrincipal User owner, @PathVariable Long id) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            FidelityTier tier = fidelityTierRepository.findById(id)
                    .orElseThrow(() -> new RuntimeException("Tier not found"));

            if (!tier.getBusiness().getId().equals(business.getId())) {
                return ResponseEntity.status(403).body(Map.of("error", "No tienes permiso para eliminar este tier"));
            }

            fidelityTierRepository.delete(tier);
            return ResponseEntity.ok(Map.of("message", "Tier eliminado correctamente"));
        } catch (Exception e) {
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }
}

package com.loyalty.controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.nio.file.Path;
import java.nio.file.Paths;

@RestController
@RequestMapping("/api/files")
public class FileController {

    @Value("${file.upload-dir}")
    private String uploadDir;

    @GetMapping("/{type}/{filename}")
    public ResponseEntity<Resource> getFile(
            @PathVariable String type,
            @PathVariable String filename) {

        try {
            // Construir la ruta completa del archivo
            Path filePath = Paths.get(uploadDir, type, filename);
            Resource resource = new UrlResource(filePath.toUri());

            // Verificar si el archivo existe y es legible
            if (resource.exists() && resource.isReadable()) {

                // Determinar el tipo de contenido basado en la extensiÃ³n
                String contentType = "application/octet-stream";
                String lowerFilename = filename.toLowerCase();

                if (lowerFilename.endsWith(".jpg") || lowerFilename.endsWith(".jpeg")) {
                    contentType = "image/jpeg";
                } else if (lowerFilename.endsWith(".png")) {
                    contentType = "image/png";
                } else if (lowerFilename.endsWith(".gif")) {
                    contentType = "image/gif";
                } else if (lowerFilename.endsWith(".svg")) {
                    contentType = "image/svg+xml";
                } else if (lowerFilename.endsWith(".webp")) {
                    contentType = "image/webp";
                }

                return ResponseEntity.ok()
                        .header(HttpHeaders.CONTENT_DISPOSITION, "inline; filename=\"" + filename + "\"")
                        .contentType(MediaType.parseMediaType(contentType))
                        .body(resource);
            } else {
                return ResponseEntity.notFound().build();
            }
        } catch (Exception e) {
            return ResponseEntity.notFound().build();
        }
    }
}

package com.loyalty.controller;

import com.loyalty.dto.RewardRedemptionDto;
import com.loyalty.entity.*;
import com.loyalty.repository.*;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

import java.time.LocalDateTime;
import java.util.Map;

@RestController
@RequestMapping("/api/customer/redemptions")
public class RewardRedemptionController {

    private final RewardRepository rewardRepository;
    private final FidelityRewardRepository fidelityRewardRepository;

    public RewardRedemptionController(
            RewardRepository rewardRepository,
            FidelityRewardRepository fidelityRewardRepository) {
        this.rewardRepository = rewardRepository;
        this.fidelityRewardRepository = fidelityRewardRepository;
    }

    @PostMapping("/request")
    public ResponseEntity<?> requestRedemption(
            @AuthenticationPrincipal User customer,
            @RequestBody RewardRedemptionDto.Request request) {

        try {
            if ("CARD".equals(request.getRewardType())) {
                Reward reward = rewardRepository.findById(request.getRewardId())
                        .orElseThrow(() -> new RuntimeException("Reward not found"));

                // Verificar que sea del cliente
                if (!reward.getLoyaltyCard().getUser().getId().equals(customer.getId())) {
                    return ResponseEntity.status(403).body(Map.of("error", "Not your reward"));
                }

                // Verificar que estÃ© disponible
                if (reward.getStatus() != Reward.RewardStatus.AVAILABLE) {
                    return ResponseEntity.badRequest().body(Map.of("error", "Reward not available"));
                }

                reward.setRequestedAt(LocalDateTime.now());
                reward.setStatus(Reward.RewardStatus.REQUESTED);
                rewardRepository.save(reward);

                return ResponseEntity.ok(new RewardRedemptionDto.Response(
                        reward.getId(), "PENDING", "Redemption requested successfully"));

            } else if ("FIDELITY".equals(request.getRewardType())) {
                FidelityReward reward = fidelityRewardRepository.findById(request.getRewardId())
                        .orElseThrow(() -> new RuntimeException("Fidelity reward not found"));

                if (!reward.getLoyaltyCard().getUser().getId().equals(customer.getId())) {
                    return ResponseEntity.status(403).body(Map.of("error", "Not your reward"));
                }

                if (reward.getStatus() != FidelityReward.RewardStatus.AVAILABLE) {
                    return ResponseEntity.badRequest().body(Map.of("error", "Reward not available"));
                }

                reward.setRequestedAt(LocalDateTime.now());
                reward.setStatus(FidelityReward.RewardStatus.REQUESTED);
                fidelityRewardRepository.save(reward);

                return ResponseEntity.ok(new RewardRedemptionDto.Response(
                        reward.getId(), "PENDING", "Redemption requested successfully"));
            }

            return ResponseEntity.badRequest().body(Map.of("error", "Invalid reward type"));

        } catch (Exception e) {
            return ResponseEntity.badRequest().body(Map.of("error", e.getMessage()));
        }
    }
}

package com.loyalty.controller;

import com.loyalty.entity.Business;
import com.loyalty.entity.BusinessTheme;
import com.loyalty.entity.User;
import com.loyalty.repository.BusinessRepository;
import com.loyalty.repository.BusinessThemeRepository;
import com.loyalty.service.FileStorageService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/admin/theme")
public class ThemeController {

    private final BusinessRepository businessRepository;
    private final BusinessThemeRepository themeRepository;
    private final FileStorageService fileStorageService;

    public ThemeController(BusinessRepository businessRepository,
                           BusinessThemeRepository themeRepository,
                           FileStorageService fileStorageService) {
        this.businessRepository = businessRepository;
        this.themeRepository = themeRepository;
        this.fileStorageService = fileStorageService;
    }

    @GetMapping("/public")
    public ResponseEntity<?> getPublicTheme() {
        try {
            Business business = businessRepository.findAll()
                    .stream()
                    .findFirst()
                    .orElseThrow(() -> new RuntimeException("No business found"));

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElseGet(() -> {
                        BusinessTheme newTheme = new BusinessTheme();
                        newTheme.setBusiness(business);
                        return themeRepository.save(newTheme);
                    });

            return ResponseEntity.ok(theme);

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }

    @GetMapping
    public ResponseEntity<?> getTheme(@AuthenticationPrincipal User owner) {
        try {
            if (owner == null) {
                return ResponseEntity.status(401).body(Map.of("error", "Usuario no autenticado"));
            }

            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found for user: " + owner.getEmail()));

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElseGet(() -> {
                        BusinessTheme newTheme = new BusinessTheme();
                        newTheme.setBusiness(business);
                        return themeRepository.save(newTheme);
                    });

            return ResponseEntity.ok(theme);

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of(
                    "error", e.getMessage(),
                    "type", e.getClass().getSimpleName()
            ));
        }
    }

    @PutMapping
    public ResponseEntity<?> updateTheme(
            @AuthenticationPrincipal User owner,
            @RequestBody BusinessTheme updatedTheme) {

        try {
            if (owner == null) {
                return ResponseEntity.status(401).body(Map.of("error", "Usuario no autenticado"));
            }

            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found for user: " + owner.getEmail()));

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElse(new BusinessTheme());

            theme.setBusiness(business);
            theme.setMode(updatedTheme.getMode());
            theme.setPrimaryColor(updatedTheme.getPrimaryColor());
            theme.setSecondaryColor(updatedTheme.getSecondaryColor());
            theme.setAccentColor(updatedTheme.getAccentColor());
            theme.setFontFamily(updatedTheme.getFontFamily());
            theme.setAppName(updatedTheme.getAppName());
            theme.setLogoSize(updatedTheme.getLogoSize());
            theme.setNameSize(updatedTheme.getNameSize());
            theme.setNavbarTextColor(updatedTheme.getNavbarTextColor());
            theme.setBackgroundSize(updatedTheme.getBackgroundSize());
            theme.setBackgroundBlur(updatedTheme.getBackgroundBlur());
            theme.setCardOpacity(updatedTheme.getCardOpacity());

            // IMPORTANTE: NO tocamos logoUrl ni backgroundUrl aquÃ­

            BusinessTheme saved = themeRepository.save(theme);
            return ResponseEntity.ok(saved);

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of(
                    "error", e.getMessage(),
                    "type", e.getClass().getSimpleName()
            ));
        }
    }

    @PostMapping("/upload-logo")
    public ResponseEntity<?> uploadLogo(
            @AuthenticationPrincipal User owner,
            @RequestParam("file") MultipartFile file) {

        try {
            if (owner == null) {
                return ResponseEntity.status(401).body(Map.of("error", "Usuario no autenticado"));
            }

            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found for user: " + owner.getEmail()));

            String fileUrl = fileStorageService.storeFile(file, "logos");

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElse(new BusinessTheme());

            if (theme.getLogoUrl() != null && !theme.getLogoUrl().isEmpty()) {
                fileStorageService.deleteFile(theme.getLogoUrl());
            }

            theme.setBusiness(business);
            theme.setLogoUrl(fileUrl);
            themeRepository.save(theme);

            Map<String, String> response = new HashMap<>();
            response.put("url", fileUrl);
            return ResponseEntity.ok(response);

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of(
                    "error", e.getMessage(),
                    "type", e.getClass().getSimpleName()
            ));
        }
    }

    @PostMapping("/upload-background")
    public ResponseEntity<?> uploadBackground(
            @AuthenticationPrincipal User owner,
            @RequestParam("file") MultipartFile file) {

        try {
            if (owner == null) {
                return ResponseEntity.status(401).body(Map.of("error", "Usuario no autenticado"));
            }

            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found for user: " + owner.getEmail()));

            String fileUrl = fileStorageService.storeFile(file, "backgrounds");

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElse(new BusinessTheme());

            if (theme.getBackgroundUrl() != null && !theme.getBackgroundUrl().isEmpty()) {
                fileStorageService.deleteFile(theme.getBackgroundUrl());
            }

            theme.setBusiness(business);
            theme.setBackgroundUrl(fileUrl);
            themeRepository.save(theme);

            Map<String, String> response = new HashMap<>();
            response.put("url", fileUrl);
            return ResponseEntity.ok(response);

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of(
                    "error", e.getMessage(),
                    "type", e.getClass().getSimpleName()
            ));
        }
    }

    @DeleteMapping("/remove-logo")
    public ResponseEntity<?> removeLogo(@AuthenticationPrincipal User owner) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElseThrow(() -> new RuntimeException("Theme not found"));

            if (theme.getLogoUrl() != null && !theme.getLogoUrl().isEmpty()) {
                fileStorageService.deleteFile(theme.getLogoUrl());
            }

            theme.setLogoUrl("");
            themeRepository.save(theme);

            return ResponseEntity.ok(Map.of("message", "Logo removed successfully"));

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }

    @DeleteMapping("/remove-background")
    public ResponseEntity<?> removeBackground(@AuthenticationPrincipal User owner) {
        try {
            Business business = businessRepository.findByOwner(owner)
                    .orElseThrow(() -> new RuntimeException("Business not found"));

            BusinessTheme theme = themeRepository.findByBusiness(business)
                    .orElseThrow(() -> new RuntimeException("Theme not found"));

            if (theme.getBackgroundUrl() != null && !theme.getBackgroundUrl().isEmpty()) {
                fileStorageService.deleteFile(theme.getBackgroundUrl());
            }

            theme.setBackgroundUrl("");
            themeRepository.save(theme);

            return ResponseEntity.ok(Map.of("message", "Background removed successfully"));

        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(Map.of("error", e.getMessage()));
        }
    }
}

package com.loyalty.controller;

import com.loyalty.dto.UserManagementDto;
import com.loyalty.entity.User;
import com.loyalty.service.UserManagementService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/admin/users")
public class UserManagementController {

    private final UserManagementService userManagementService;

    public UserManagementController(UserManagementService userManagementService) {
        this.userManagementService = userManagementService;
    }

    // GET /api/admin/users â€” list all users
    @GetMapping
    public ResponseEntity<List<UserManagementDto>> getAllUsers() {
        return ResponseEntity.ok(userManagementService.getAllUsers());
    }

    // POST /api/admin/users â€” create user with any role
    @PostMapping
    public ResponseEntity<UserManagementDto> createUser(
            @RequestBody UserManagementDto.CreateRequest request) {
        return ResponseEntity.ok(userManagementService.createUser(request));
    }

    // PATCH /api/admin/users/{id}/role â€” change role of existing user
    @PatchMapping("/{id}/role")
    public ResponseEntity<UserManagementDto> updateRole(
            @PathVariable Long id,
            @RequestBody UserManagementDto.UpdateRoleRequest request) {
        return ResponseEntity.ok(userManagementService.updateUserRole(id, request.getRole()));
    }

    // DELETE /api/admin/users/{id} â€” delete user
    @DeleteMapping("/{id}")
    public ResponseEntity<Map<String, String>> deleteUser(
            @PathVariable Long id,
            @AuthenticationPrincipal User admin) {
        userManagementService.deleteUser(id, admin);
        return ResponseEntity.ok(Map.of("message", "User deleted successfully"));
    }
}

