package com.loyalty.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.lang.NonNull;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtService jwtService;
    private final UserDetailsService userDetailsService;

    public JwtAuthenticationFilter(JwtService jwtService, UserDetailsService userDetailsService) {
        this.jwtService = jwtService;
        this.userDetailsService = userDetailsService;
    }

    @Override
    protected void doFilterInternal(
            @NonNull HttpServletRequest request,
            @NonNull HttpServletResponse response,
            @NonNull FilterChain filterChain
    ) throws ServletException, IOException {
        final String authHeader = request.getHeader("Authorization");
        final String jwt;
        final String userEmail;

        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            filterChain.doFilter(request, response);
            return;
        }

        jwt = authHeader.substring(7);
        userEmail = jwtService.extractUsername(jwt);

        if (userEmail != null && SecurityContextHolder.getContext().getAuthentication() == null) {
            UserDetails userDetails = this.userDetailsService.loadUserByUsername(userEmail);
            if (jwtService.isTokenValid(jwt, userDetails)) {
                UsernamePasswordAuthenticationToken authToken = new UsernamePasswordAuthenticationToken(
                        userDetails, null, userDetails.getAuthorities()
                );
                authToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(authToken);
            }
        }

        filterChain.doFilter(request, response);
    }
}

package com.loyalty.security;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

@Service
public class JwtService {

    @Value("${app.jwt.secret}")
    private String secretKey;

    @Value("${app.jwt.expiration}")
    private long jwtExpiration;

    public String extractUsername(String token) {
        return extractClaim(token, Claims::getSubject);
    }

    public <T> T extractClaim(String token, Function<Claims, T> claimsResolver) {
        final Claims claims = extractAllClaims(token);
        return claimsResolver.apply(claims);
    }

    public String generateToken(UserDetails userDetails) {
        return generateToken(new HashMap<>(), userDetails);
    }

    public String generateToken(Map<String, Object> extraClaims, UserDetails userDetails) {
        return buildToken(extraClaims, userDetails, jwtExpiration);
    }

    private String buildToken(Map<String, Object> extraClaims, UserDetails userDetails, long expiration) {
        return Jwts.builder()
                .claims(extraClaims)
                .subject(userDetails.getUsername())
                .issuedAt(new Date(System.currentTimeMillis()))
                .expiration(new Date(System.currentTimeMillis() + expiration))
                .signWith(getSignInKey())
                .compact();
    }

    public boolean isTokenValid(String token, UserDetails userDetails) {
        final String username = extractUsername(token);
        return username.equals(userDetails.getUsername()) && !isTokenExpired(token);
    }

    private boolean isTokenExpired(String token) {
        return extractExpiration(token).before(new Date());
    }

    private Date extractExpiration(String token) {
        return extractClaim(token, Claims::getExpiration);
    }

    private Claims extractAllClaims(String token) {
        return Jwts.parser()
                .verifyWith(getSignInKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    private SecretKey getSignInKey() {
        byte[] keyBytes = secretKey.getBytes(StandardCharsets.UTF_8);
        return Keys.hmacShaKeyFor(keyBytes);
    }
}

package com.loyalty.service;

import com.loyalty.dto.AuthDto;
import com.loyalty.entity.Business;
import com.loyalty.entity.LoyaltyCard;
import com.loyalty.entity.User;
import com.loyalty.repository.BusinessRepository;
import com.loyalty.repository.LoyaltyCardRepository;
import com.loyalty.repository.UserRepository;
import com.loyalty.security.JwtService;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AuthService {

    private final UserRepository userRepository;
    private final BusinessRepository businessRepository;
    private final LoyaltyCardRepository loyaltyCardRepository;
    private final PasswordEncoder passwordEncoder;
    private final JwtService jwtService;
    private final AuthenticationManager authenticationManager;
    private final QrCodeService qrCodeService;

    public AuthService(UserRepository userRepository, BusinessRepository businessRepository, LoyaltyCardRepository loyaltyCardRepository, PasswordEncoder passwordEncoder, JwtService jwtService, AuthenticationManager authenticationManager, QrCodeService qrCodeService) {
        this.userRepository = userRepository;
        this.businessRepository = businessRepository;
        this.loyaltyCardRepository = loyaltyCardRepository;
        this.passwordEncoder = passwordEncoder;
        this.jwtService = jwtService;
        this.authenticationManager = authenticationManager;
        this.qrCodeService = qrCodeService;
    }

    @Transactional
    public AuthDto.AuthResponse register(AuthDto.RegisterRequest request) {
        if (userRepository.existsByEmail(request.getEmail())) {
            throw new IllegalArgumentException("Email already registered");
        }

        User.Role role = User.Role.valueOf(request.getRole().toUpperCase());
        String qrCodeId = qrCodeService.generateQrCodeId();

        User user = User.builder()
                .email(request.getEmail())
                .password(passwordEncoder.encode(request.getPassword()))
                .firstName(request.getFirstName())
                .lastName(request.getLastName())
                .phone(request.getPhone())
                .role(role)
                .qrCode(qrCodeId)
                .build();

        User savedUser = userRepository.save(user);

        if (role == User.Role.CUSTOMER) {
            // Get the default business (first business, or create one)
            Business business = businessRepository.findAll().stream()
                    .findFirst()
                    .orElseGet(() -> createDefaultBusiness(savedUser));

            LoyaltyCard loyaltyCard = LoyaltyCard.builder()
                    .user(savedUser)
                    .business(business)
                    .totalStamps(business.getStampsRequired())
                    .currentStamps(0)
                    .completedCards(0)
                    .status(LoyaltyCard.CardStatus.ACTIVE)
                    .build();

            loyaltyCardRepository.save(loyaltyCard);
        } else if (role == User.Role.BUSINESS_OWNER) {
            Business business = Business.builder()
                    .name(request.getFirstName() + "'s Coffee Shop")
                    .description("Welcome to our loyalty program!")
                    .stampsRequired(10)
                    .rewardDescription("Buy 10 coffees, get 1 FREE!")
                    .owner(savedUser)
                    .build();
            businessRepository.save(business);
        }

        String jwtToken = jwtService.generateToken(savedUser);
        return new AuthDto.AuthResponse(
                jwtToken, savedUser.getEmail(),
                savedUser.getFirstName(), savedUser.getLastName(),
                savedUser.getRole().name(), savedUser.getId()
        );
    }

    public AuthDto.AuthResponse login(AuthDto.LoginRequest request) {
        authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(request.getEmail(), request.getPassword())
        );

        User user = userRepository.findByEmail(request.getEmail())
                .orElseThrow(() -> new IllegalArgumentException("User not found"));

        String jwtToken = jwtService.generateToken(user);
        return new AuthDto.AuthResponse(
                jwtToken, user.getEmail(),
                user.getFirstName(), user.getLastName(),
                user.getRole().name(), user.getId()
        );
    }

    private Business createDefaultBusiness(User owner) {
        Business business = Business.builder()
                .name("Loyalty Coffee Shop")
                .description("Your neighborhood coffee shop")
                .stampsRequired(10)
                .rewardDescription("Buy 10 coffees, get 1 FREE!")
                .owner(owner)
                .build();
        return businessRepository.save(business);
    }
}

package com.loyalty.service;

import com.loyalty.dto.BusinessDto;
import com.loyalty.entity.Business;
import com.loyalty.entity.User;
import com.loyalty.repository.BusinessRepository;
import com.loyalty.repository.LoyaltyCardRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class BusinessService {

    private final BusinessRepository businessRepository;
    private final LoyaltyCardRepository loyaltyCardRepository;

    public BusinessService(BusinessRepository businessRepository, LoyaltyCardRepository loyaltyCardRepository) {
        this.businessRepository = businessRepository;
        this.loyaltyCardRepository = loyaltyCardRepository;
    }

    public BusinessDto getMyBusiness(User owner) {
        Business business = businessRepository.findByOwner(owner)
                .orElseThrow(() -> new RuntimeException("No business found for this owner"));
        return mapToDto(business);
    }

    @Transactional
    public BusinessDto updateBusiness(User owner, BusinessDto request) {
        Business business = businessRepository.findByOwner(owner)
                .orElseThrow(() -> new RuntimeException("No business found for this owner"));

        if (request.getName() != null)              business.setName(request.getName());
        if (request.getDescription() != null)       business.setDescription(request.getDescription());
        if (request.getLogoUrl() != null)           business.setLogoUrl(request.getLogoUrl());
        if (request.getRewardDescription() != null) business.setRewardDescription(request.getRewardDescription());
        if (request.getStampsRequired() != null && request.getStampsRequired() > 0) {
            business.setStampsRequired(request.getStampsRequired());
        }

        Business saved = businessRepository.save(business);
        return mapToDto(saved);
    }

    private BusinessDto mapToDto(Business business) {
        long customerCount = loyaltyCardRepository.findAll().stream()
                .filter(c -> c.getBusiness().getId().equals(business.getId()))
                .count();

        return BusinessDto.builder()
                .id(business.getId())
                .name(business.getName())
                .description(business.getDescription())
                .logoUrl(business.getLogoUrl())
                .stampsRequired(business.getStampsRequired())
                .rewardDescription(business.getRewardDescription())
                .ownerId(business.getOwner().getId())
                .ownerName(business.getOwner().getFirstName() + " " + business.getOwner().getLastName())
                .totalCustomers((int) customerCount)
                .createdAt(business.getCreatedAt())
                .build();
    }
}

package com.loyalty.service;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.util.StringUtils;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.UUID;

@Service
public class FileStorageService {

    @Value("${file.upload-dir}")
    private String uploadDir;

    /**
     * Guarda un archivo en el servidor
     * @param file El archivo a guardar
     * @param subfolder Subcarpeta (logos o backgrounds)
     * @return La URL pÃºblica del archivo
     * @throws IOException Si hay error al guardar
     */
    public String storeFile(MultipartFile file, String subfolder) throws IOException {
        // Crear el directorio si no existe
        Path uploadPath = Paths.get(uploadDir, subfolder);
        if (!Files.exists(uploadPath)) {
            Files.createDirectories(uploadPath);
        }

        // Generar nombre Ãºnico para evitar conflictos
        String originalFilename = StringUtils.cleanPath(file.getOriginalFilename());
        String extension = "";
        if (originalFilename.contains(".")) {
            extension = originalFilename.substring(originalFilename.lastIndexOf("."));
        } else {
            extension = ".png"; // default
        }

        String filename = UUID.randomUUID().toString() + extension;

        // Guardar el archivo
        Path filePath = uploadPath.resolve(filename);
        Files.copy(file.getInputStream(), filePath, StandardCopyOption.REPLACE_EXISTING);

        // Retornar la URL pÃºblica (relativa)
        return "/uploads/" + subfolder + "/" + filename;
    }

    /**
     * Elimina un archivo del servidor
     * @param fileUrl La URL del archivo a eliminar
     */
    public void deleteFile(String fileUrl) {
        if (fileUrl == null || fileUrl.isEmpty()) return;

        try {
            // Extraer nombre del archivo de la URL
            String filename = fileUrl.substring(fileUrl.lastIndexOf("/") + 1);
            String subfolder = fileUrl.contains("/logos/") ? "logos" : "backgrounds";

            Path filePath = Paths.get(uploadDir, subfolder, filename);
            Files.deleteIfExists(filePath);
        } catch (IOException e) {
            // Solo loguear, no interrumpir flujo
            System.err.println("Error deleting file: " + e.getMessage());
        }
    }
}

