      }

      // Verificar permisos (esto dispara el prompt)
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        }
      });

      // Si llegamos acÃ¡, hay permiso
      stream.getTracks().forEach(track => track.stop());

      this.cameraStatus = 'âœ… Permiso concedido, iniciando escÃ¡ner...';

      // Inicializar escÃ¡ner
      this.html5QrCode = new Html5Qrcode('qr-reader');
      this.scannerActive = true;

      const config = {
        fps: 10,
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0
      };

      await this.html5QrCode.start(
        { facingMode: 'environment' },
        config,
        (decodedText: string) => {
          console.log('âœ… QR detectado:', decodedText);
          this.cameraStatus = 'âœ… QR detectado!';
          this.html5QrCode.pause();
          this.processQrCode(decodedText);
        },
        (errorMessage: string) => {
          // Ignorar errores de escaneo (son normales mientras busca)
          if (!errorMessage.includes('NotFoundException')) {
            console.log('âš ï¸', errorMessage);
          }
        }
      );

      this.cameraStatus = 'âœ… EscÃ¡ner activo. ApuntÃ¡ a un cÃ³digo QR.';

    } catch (err: any) {
      console.error('âŒ Error de cÃ¡mara:', err);
      this.cameraError = true;
      this.scannerActive = false;

      if (err.name === 'NotAllowedError' || err.message.includes('permission')) {
        this.cameraStatus = 'âŒ Permiso denegado. HacÃ© click en el candado ðŸ”’ y permitÃ­ la cÃ¡mara.';
      } else if (err.name === 'NotFoundError') {
        this.cameraStatus = 'âŒ No se encontrÃ³ ninguna cÃ¡mara.';
      } else {
        this.cameraStatus = 'âŒ Error: ' + (err.message || 'desconocido');
      }
    }
  }

  stopScanner() {
    if (this.html5QrCode && this.scannerActive) {
      this.html5QrCode.stop().then(() => {
        this.html5QrCode.clear();
        this.html5QrCode = null;
        this.scannerActive = false;
        this.cameraStatus = 'â¹ï¸ EscÃ¡ner detenido';
      }).catch(console.error);
    }
  }

  async processQrCode(qrCode: string) {
    this.error = '';
    try {
      const card = await this.loyaltyService.scanQrAndAddStamp({
        qrCode,
        note: ''
      }).toPromise();

      if (card) {
        this.scannedCard = card;
        this.manualCode = qrCode;
        this.stopScanner();
      } else {
        this.error = 'Error: No se pudo obtener la tarjeta';
      }

    } catch (err: any) {
      this.error = err.error?.error || 'QR invÃ¡lido';
      // Reanudar escÃ¡ner
      if (this.html5QrCode) {
        this.html5QrCode.resume();
      }
    }
  }

  scanManual() {
    if (!this.manualCode.trim()) return;
    this.stopScanner();
    this.processQrCode(this.manualCode.trim());
  }

  addStamp() {
    if (!this.scannedCard) return;

    this.addingStamp = true;
    this.error = '';

    this.loyaltyService.addStamp({
      userId: this.scannedCard.userId,
      note: this.stampNote
    }).subscribe({
      next: (card) => {
        this.scannedCard = card;
        this.success = 'âœ… Sello agregado correctamente';
        this.addingStamp = false;
        this.stampNote = '';
        setTimeout(() => this.success = '', 3000);
      },
      error: (err) => {
        this.error = err.error?.error || 'Error al agregar sello';
        this.addingStamp = false;
      }
    });
  }

  clearScan() {
    this.scannedCard = null;
    this.manualCode = '';
    this.stampNote = '';
    this.error = '';
  }
}

