export class UserManagementComponent implements OnInit {
  private readonly API = `${environment.apiUrl}/admin/users`;

  users: ManagedUser[] = [];
  loading = true;
  creating = false;
  deletingId: number | null = null;
  showForm = false;
  filterQuery = '';
  success = '';
  error = '';
  userToDelete: ManagedUser | null = null;

  newUser: CreateUserForm = {
    firstName: '', lastName: '', email: '',
    phone: '', password: '', role: 'CUSTOMER'
  };

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.loadUsers();
  }

  get filteredUsers(): ManagedUser[] {
    const q = this.filterQuery.toLowerCase();
    if (!q) return this.users;
    return this.users.filter(u =>
      u.firstName.toLowerCase().includes(q) ||
      u.lastName.toLowerCase().includes(q) ||
      u.email.toLowerCase().includes(q)
    );
  }

  loadUsers() {
    this.loading = true;
    this.http.get<ManagedUser[]>(this.API).subscribe({
      next: (users) => { this.users = users; this.loading = false; },
      error: () => { this.error = 'Error cargando usuarios'; this.loading = false; }
    });
  }

  createUser() {
    if (!this.newUser.firstName || !this.newUser.email || !this.newUser.password) {
      this.error = 'CompletÃ¡ todos los campos obligatorios';
      return;
    }
    this.creating = true;
    this.http.post<ManagedUser>(this.API, this.newUser).subscribe({
      next: (user) => {
        this.users.unshift(user);
        this.showForm = false;
        this.newUser = { firstName: '', lastName: '', email: '', phone: '', password: '', role: 'CUSTOMER' };
        this.showSuccess('Usuario creado correctamente');
        this.creating = false;
      },
      error: (err) => {
        this.error = err.error?.error || 'Error al crear el usuario';
        this.creating = false;
      }
    });
  }

  changeRole(user: ManagedUser, newRole: string) {
    this.http.patch<ManagedUser>(`${this.API}/${user.id}/role`, { role: newRole }).subscribe({
      next: (updated) => {
        user.role = updated.role;
        this.showSuccess(`Rol actualizado a ${newRole === 'BUSINESS_OWNER' ? 'Admin' : 'Cliente'}`);
      },
      error: () => { this.error = 'Error al cambiar el rol'; }
    });
  }

  confirmDelete(user: ManagedUser) {
    this.userToDelete = user;
  }

  deleteUser() {
    if (!this.userToDelete) return;
    this.deletingId = this.userToDelete.id;
    this.http.delete(`${this.API}/${this.userToDelete.id}`).subscribe({
      next: () => {
        this.users = this.users.filter(u => u.id !== this.userToDelete!.id);
        this.showSuccess('Usuario eliminado');
        this.userToDelete = null;
        this.deletingId = null;
      },
      error: (err) => {
        this.error = err.error?.error || 'Error al eliminar';
        this.userToDelete = null;
        this.deletingId = null;
      }
    });
  }

  private showSuccess(msg: string) {
    this.success = msg;
    this.error = '';
    setTimeout(() => this.success = '', 3500);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, tap } from 'rxjs';
import { Router } from '@angular/router';
import { environment } from '../../environments/environment';

export interface AuthRequest {
  email: string;
  password: string;
}

export interface RegisterRequest {
  email: string;
  password: string;
  firstName: string;
  lastName: string;
  phone?: string;
  role: string;
}

export interface AuthResponse {
  token: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  userId: number;
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private readonly API = `${environment.apiUrl}/auth`;

  constructor(
    private http: HttpClient,
    private router: Router
  ) {}

  register(request: RegisterRequest): Observable<AuthResponse> {
    return this.http.post<AuthResponse>(`${this.API}/register`, request).pipe(
      tap(res => this.saveSession(res))
    );
  }

  login(request: AuthRequest): Observable<AuthResponse> {
    return this.http.post<AuthResponse>(`${this.API}/login`, request).pipe(
      tap(res => this.saveSession(res))
    );
  }

  logout(): void {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    this.router.navigate(['/login']);
  }

  getToken(): string | null {
    return localStorage.getItem('token');
  }

  getUser(): AuthResponse | null {
    const user = localStorage.getItem('user');
    return user ? JSON.parse(user) : null;
  }

  isLoggedIn(): boolean {
    return !!this.getToken();
  }

  getRole(): string | null {
    return this.getUser()?.role ?? null;
  }

  isCustomer(): boolean {
    return this.getRole() === 'CUSTOMER';
  }

  isAdmin(): boolean {
    return this.getRole() === 'BUSINESS_OWNER';
  }

  private saveSession(res: AuthResponse): void {
    localStorage.setItem('token', res.token);
    localStorage.setItem('user', JSON.stringify(res));
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AddStampRequest, Customer, LoyaltyCard, ScanQrRequest } from '../models/models';
import { environment } from '../../environments/environment';

@Injectable({ providedIn: 'root' })
export class LoyaltyService {
  private readonly CUSTOMER_API = `${environment.apiUrl}/customer`;
  private readonly ADMIN_API = `${environment.apiUrl}/admin`;

  constructor(private http: HttpClient) {}

  // Customer endpoints
  getMyCard(): Observable<LoyaltyCard> {
    return this.http.get<LoyaltyCard>(`${this.CUSTOMER_API}/card`);
  }

  getMyQrCode(): Observable<string> {
    return this.http.get(`${this.CUSTOMER_API}/qr`, { responseType: 'text' });
  }

  // NUEVO: Solicitar canje de recompensa
  requestRedemption(request: { rewardId: number, rewardType: string }): Observable<any> {
    return this.http.post(`${this.CUSTOMER_API}/redemptions/request`, request);
  }

  // Admin endpoints
  getAllCustomers(): Observable<Customer[]> {
    return this.http.get<Customer[]>(`${this.ADMIN_API}/customers`);
  }

  searchCustomers(query: string): Observable<Customer[]> {
    return this.http.get<Customer[]>(`${this.ADMIN_API}/customers/search`, {
      params: { q: query }
    });
  }

  getCustomerCard(userId: number): Observable<LoyaltyCard> {
    return this.http.get<LoyaltyCard>(`${this.ADMIN_API}/customers/${userId}/card`);
  }

  addStamp(request: AddStampRequest): Observable<LoyaltyCard> {
    return this.http.post<LoyaltyCard>(`${this.ADMIN_API}/stamps`, request);
  }

  scanQrAndAddStamp(request: ScanQrRequest): Observable<LoyaltyCard> {
    return this.http.post<LoyaltyCard>(`${this.ADMIN_API}/stamps/scan`, request);
  }

  getCustomerQr(userId: number): Observable<{ qrCode: string }> {
    return this.http.get<{ qrCode: string }>(`${this.ADMIN_API}/customers/${userId}/qr`);
  }
}

