}
.alert-success { background: rgba(6,214,160,0.2); color: #059669; border: 1px solid rgba(6,214,160,0.3); }
.alert-error { background: rgba(239,71,111,0.2); color: #dc2626; border: 1px solid rgba(239,71,111,0.25); }
.alert-warning { background: rgba(255,183,3,0.2); color: #d97706; border: 1px solid rgba(255,183,3,0.3); }

[data-theme="dark"] .alert-success { color: #34d399; }
[data-theme="dark"] .alert-error { color: #f87171; }

/* ===== TARJETA DE LEALTAD ===== */
.loyalty-card-visual {
  background: linear-gradient(135deg, var(--secondary) 0%, color-mix(in srgb, var(--secondary) 70%, var(--primary)) 100%);
  border-radius: var(--radius-xl);
  padding: 28px 24px;
  color: white;
  margin-bottom: 20px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.loyalty-card-visual::before {
  content: '';
  position: absolute;
  top: -40px; right: -40px;
  width: 200px; height: 200px;
  background: radial-gradient(circle, rgba(255,255,255,0.06) 0%, transparent 70%);
  border-radius: 50%;
}
.loyalty-card-business { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 2px; opacity: 0.6; margin-bottom: 6px; }
.loyalty-card-name { font-family: var(--font-display); font-size: 1.3rem; font-weight: 700; margin-bottom: 6px; }
.loyalty-card-reward { font-size: 0.85rem; opacity: 0.75; margin-bottom: 20px; }

.stamp-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; }
.stamp-cell {
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  border: 1.5px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.05);
  transition: all var(--transition);
}
.stamp-cell.filled {
  background: var(--primary);
  border-color: var(--primary);
  box-shadow: 0 2px 8px rgba(255,107,53,0.4);
  transform: scale(1.02);
}
.stamp-cell.empty { color: rgba(255,255,255,0.35); font-size: 0.7rem; }

/* ===== BARRA DE PROGRESO ===== */
.progress-bar {
  height: 6px;
  background: rgba(255,255,255,0.15);
  border-radius: 99px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: var(--primary);
  border-radius: 99px;
  transition: width 0.5s ease;
}

/* ===== GRID DE ESTADÃSTICAS ===== */
.stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px; }
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  text-align: center;
  transition: box-shadow var(--transition);
  backdrop-filter: blur(8px);
}
.stat-card:hover { box-shadow: var(--shadow-md); }
.stat-value { font-family: var(--font-display); font-size: 1.8rem; font-weight: 800; color: var(--primary); }
.stat-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 2px; text-transform: uppercase; letter-spacing: 0.5px; }

/* ===== DASHBOARD ===== */
.dashboard-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
.stat-card-big {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
  transition: box-shadow var(--transition), transform var(--transition);
  backdrop-filter: blur(8px);
}
.stat-card-big:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.stat-icon { font-size: 2rem; }

.quick-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 24px; }
.action-card {
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  text-decoration: none;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  border: 1.5px solid transparent;
  backdrop-filter: blur(8px);
}
.action-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.action-primary { background: var(--primary); color: white; }
.action-secondary { background: var(--surface); border-color: var(--border); color: var(--text-primary); }
.action-icon { font-size: 2rem; }
.action-text { font-weight: 600; font-size: 0.9rem; }

/* ===== LISTA DE CLIENTES ===== */
.customer-card-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: var(--radius-md);
  transition: background var(--transition);
  cursor: pointer;
}
.customer-card-item:hover { background: var(--surface-2); }

.avatar {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.85rem;
  font-family: var(--font-display);
  flex-shrink: 0;
}

/* ===== BADGES ===== */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 99px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}
.badge-primary { background: var(--primary-light); color: var(--primary); }
.badge-success { background: rgba(6,214,160,0.12); color: #059669; }
.badge-warning { background: rgba(255,183,3,0.15); color: #b45309; }

/* ===== BARRA DE BÃšSQUEDA ===== */
.search-bar {
  position: relative;
  margin-bottom: 20px;
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.9rem;
}
.search-input {
  width: 100%;
  padding: 10px 16px 10px 40px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--text-primary);
  background: var(--surface);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
  box-sizing: border-box;
}
.search-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 15%, transparent);
}
.search-input::placeholder { color: var(--text-muted); }

/* ===== QR ===== */
.qr-container {
  background: white;
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-lg);
  display: inline-block;
}
.qr-container img { width: 220px; height: 220px; display: block; }

/* ===== ENCABEZADO DE PÃGINA ===== */
.page-header { margin-bottom: 24px; }
.page-title {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 4px;
}
.page-subtitle { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== SPINNER ===== */
.spinner {
  width: 32px; height: 32px;
  border: 3px solid var(--border);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  margin: 0 auto;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ===== ANIMACIONES ===== */
.fade-in { animation: fadeIn 0.35s ease forwards; }
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ===== ESTILOS PARA APARIENCIA ===== */
.theme-btn {
  padding: 12px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
  cursor: pointer;
  font-family: var(--font-body);
  font-weight: 600;
  color: var(--text-primary);
  transition: all var(--transition);
  text-align: center;
  backdrop-filter: blur(8px);
  font-size: 0.9rem;
}
.theme-btn:hover { border-color: var(--primary); }
.theme-btn.active { border-color: var(--primary); background: var(--primary-light); color: var(--primary); }

.color-picker-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.color-picker-row input[type="color"] {
  width: 40px; height: 40px;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  padding: 2px;
  background: transparent;
}
.color-picker-row label {
  font-size: 0.85rem;
  color: var(--text-secondary);
  font-weight: 500;
  flex: 1;
}

.font-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.font-btn {
  padding: 10px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
  cursor: pointer;
  text-align: center;
  transition: all var(--transition);
  font-size: 0.85rem;
  color: var(--text-primary);
  backdrop-filter: blur(8px);
}
.font-btn:hover { border-color: var(--primary); }
.font-btn.active { border-color: var(--primary); background: var(--primary-light); color: var(--primary); font-weight: 600; }

/* ===== MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
  padding: 16px;
  backdrop-filter: blur(4px);
}

.modal-box {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: 28px;
  max-width: 400px;
  width: 100%;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--border);
  animation: fadeIn 0.2s ease;
  backdrop-filter: blur(16px);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .dashboard-stats { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .font-grid { grid-template-columns: 1fr 1fr; }
  .auth-card { padding: 24px 20px; }
}

@media (max-width: 480px) {
  .quick-actions { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .navbar-nav { display: none; }
}

