package com.loyalty.repository;

import com.loyalty.entity.Business;
import com.loyalty.entity.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;
import java.util.Optional;

@Repository
public interface BusinessRepository extends JpaRepository<Business, Long> {
    Optional<Business> findByOwner(User owner);
}

package com.loyalty.repository;

import com.loyalty.entity.LoyaltyCard;
import com.loyalty.entity.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;
import java.util.Optional;

@Repository
public interface LoyaltyCardRepository extends JpaRepository<LoyaltyCard, Long> {
    Optional<LoyaltyCard> findByUser(User user);
    Optional<LoyaltyCard> findByUserId(Long userId);
}

package com.loyalty.repository;

import com.loyalty.entity.Reward;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public interface RewardRepository extends JpaRepository<Reward, Long> {
    List<Reward> findByLoyaltyCardId(Long loyaltyCardId);
}

package com.loyalty.repository;

import com.loyalty.entity.Stamp;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public interface StampRepository extends JpaRepository<Stamp, Long> {
    List<Stamp> findByLoyaltyCardIdOrderByCreatedAtDesc(Long loyaltyCardId);
}

